  const out = JSON.parse(r.stdout);
  assert(out.ok === true && out.ts === '1700000000.123456', `unexpected output: ${r.stdout}`);
});

test('API error exits 1, prints hint to stderr, stdout empty', () => {
  const r = run(['chat.postMessage', '{"channel":"NOPE","text":"hi"}', '--token', 'xoxb-test']);
  assert(r.status === 1, `exit ${r.status}`);
  assert(r.stdout === '', 'stdout should be empty on API error');
  const err = JSON.parse(r.stderr);
  assert(err.error === 'channel_not_found', `unexpected error: ${r.stderr}`);
  assert(/channel ID/.test(err.hint), `missing hint: ${r.stderr}`);
});

test('--paginate merges pages', () => {
  const r = run(['conversations.list', '{}', '--token', 'xoxb-test', '--paginate']);
  assert(r.status === 0, `exit ${r.status}; stderr: ${r.stderr}`);
  const out = JSON.parse(r.stdout);
  assert(out.channels.length === 5, `expected 5 merged channels, got ${out.channels.length}`);
  assert(out._pagination && out._pagination.pages === 2, `missing _pagination: ${r.stdout}`);
});

test('large arrays are truncated with _truncated note', () => {
  const r = run(['conversations.history', '{}', '--token', 'xoxb-test']);
  assert(r.status === 0, `exit ${r.status}; stderr: ${r.stderr}`);
  const out = JSON.parse(r.stdout);
  assert(out.messages.length === 50, `expected 50 truncated messages, got ${out.messages.length}`);
  assert(
    out._truncated && out._truncated[0].total === 120,
    `missing _truncated note: ${r.stdout.slice(0, 300)}`,
  );
});

test('invalid_auth error carries token hint', () => {
  const r = run(['invalid_auth_test', '--token', 'xoxb-test']);
  assert(r.status === 1, `exit ${r.status}`);
  const err = JSON.parse(r.stderr);
  assert(err.error === 'invalid_auth' && /token/i.test(err.hint), `unexpected: ${r.stderr}`);
});

test('429 is retried and succeeds', () => {
  const r = run(['rate.limited', '--token', 'xoxb-test']);
  assert(r.status === 0, `exit ${r.status}; stderr: ${r.stderr}`);
  const out = JSON.parse(r.stdout);
  assert(out.ok === true && out.hits === 2, `expected retry success: ${r.stdout}`);
  assert(/Retrying after HTTP 429/.test(r.stderr), `expected retry notice: ${r.stderr}`);
});

test('5xx exhausts retries and exits 1', () => {
  const r = run(['server.error', '--token', 'xoxb-test']);
  assert(r.status === 1, `exit ${r.status}`);
  assert(/HTTP 500 after 3 attempts/.test(r.stderr), `unexpected: ${r.stderr}`);
});

test('missing token is a usage error (exit 2)', () => {
  const r = run(['auth.test'], { SLACK_TOKEN: '' });
  assert(r.status === 2, `exit ${r.status}`);
  assert(/SLACK_TOKEN/.test(r.stderr), `unexpected: ${r.stderr}`);
});

test('invalid JSON args is a usage error (exit 2)', () => {
  const r = run(['chat.postMessage', 'not json', '--token', 'xoxb-test']);
  assert(r.status === 2, `exit ${r.status}`);
  assert(/Invalid JSON args/.test(r.stderr), `unexpected: ${r.stderr}`);
});

test('unknown option is a usage error (exit 2)', () => {
  const r = run(['auth.test', '--nope', '--token', 'xoxb-test']);
  assert(r.status === 2, `exit ${r.status}`);
  assert(/Unknown option/.test(r.stderr), `unexpected: ${r.stderr}`);
});

async function main() {
  console.log(`node ${process.version}`);
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  const port = server.address().port;
  global.BASE = `http://127.0.0.1:${port}/`;

  let failed = 0;
  for (const t of tests) {
    try {
      t.fn();
      console.log(`PASS: ${t.name}`);
    } catch (err) {
      failed += 1;
      console.log(`FAIL: ${t.name}\n      ${err.message}`);
    }
  }
  server.close();
  console.log(`\n${tests.length - failed}/${tests.length} tests passed`);
  process.exit(failed === 0 ? 0 : 1);
}

main();

#!/usr/bin/env node
/**
 * Slack Web API helper — deterministic, LLM-friendly wrapper.
 *
 * Sends POST requests with JSON bodies to the Slack Web API, handles
 * authentication, cursor pagination, automatic retries on 429/5xx, and
 * truncates large arrays in the output.
 *
 * Usage:
 *   node slack_api.cjs <method> '<json-args>' [options]
 *
 * Options:
 *   --token TOKEN   Slack token (default: $SLACK_TOKEN)
 *   --url URL       API base URL (default: $SLACK_API_URL or https://slack.com/api/)
 *   --paginate      Follow response_metadata.next_cursor until exhausted (max --max-pages pages)
 *   --max-pages N   Page cap when paginating (default: 10)
 *   --max-items N   Truncate arrays longer than N in output (default: 50; 0 disables)
 *   --timeout MS    Per-request timeout in milliseconds (default: 30000)
 *   -h, --help      Show this help
 *
 * Exit codes: 0 = success, 1 = API/network error, 2 = usage error.
 *
 * Examples:
 *   node slack_api.cjs auth.test
 *   node slack_api.cjs chat.postMessage '{"channel":"C123456","text":"Deploy complete"}'
 *   node slack_api.cjs conversations.list '{"types":"public_channel"}' --paginate
 *   node slack_api.cjs chat.postMessage '{"channel":"C123456","thread_ts":"1700000000.123456","text":"Thread reply"}'
 */
'use strict';

const http = require('node:http');
const https = require('node:https');

const DEFAULT_BASE_URL = 'https://slack.com/api/';
const DEFAULT_MAX_PAGES = 10;
const DEFAULT_MAX_ITEMS = 50;
const DEFAULT_TIMEOUT_MS = 30000;
const MAX_ATTEMPTS = 3;

const USAGE = `Slack Web API helper

Usage:
  node slack_api.cjs <method> '<json-args>' [options]

Options:
  --token TOKEN   Slack token (default: \$SLACK_TOKEN)
  --url URL       API base URL (default: \$SLACK_API_URL or https://slack.com/api/)
  --paginate      Follow response_metadata.next_cursor until exhausted (max --max-pages pages)
  --max-pages N   Page cap when paginating (default: 10)
  --max-items N   Truncate arrays longer than N in output (default: 50; 0 disables)
  --timeout MS    Per-request timeout in milliseconds (default: 30000)
  -h, --help      Show this help

Exit codes: 0 = success, 1 = API/network error, 2 = usage error.

Examples:
  node slack_api.cjs auth.test
  node slack_api.cjs chat.postMessage '{"channel":"C123456","text":"Deploy complete"}'
  node slack_api.cjs conversations.list '{"types":"public_channel"}' --paginate
  node slack_api.cjs chat.postMessage '{"channel":"C123456","thread_ts":"1700000000.123456","text":"Thread reply"}'
`;

const HINTS = {
  invalid_auth:
    'Check the token (--token or $SLACK_TOKEN). Use a bot token (xoxb-...) or user token (xoxp-...).',
  invalid_auth_token:
    'The token is not valid for this workspace. Generate a fresh token from the Slack app.',
  account_inactive:
    'The token belongs to a deactivated user or app. Check the Slack app status.',
  token_revoked:
    'The token was revoked. Create a new token in the Slack app.',
  missing_scope:
    'The token lacks the required OAuth scope for this method. Add the scope to the Slack app and reinstall it.',
  not_in_channel:
    'The bot/user is not a member of that channel. Invite it first with conversations.invite.',
  channel_not_found:
    'Use a channel ID (C...), not a name. Find it with conversations.list.',
  is_archived:
    'The channel is archived. Unarchive it first with conversations.unarchive.',
  rate_limited:
    'Rate limit hit. The script retries automatically; if this persists, wait and retry.',
  invalid_arguments:
    'One of the parameters is invalid. Check the method documentation in references/api.md.',
  internal_error:
    'Slack-side error. Retry the request.',
};

class SlackApiError extends Error {
  constructor(error, hint, detail) {
    super(error);
    this.name = 'SlackApiError';
    this.error = error;
    this.hint = hint || '';
    this.detail = detail;
  }
}

function usageError(message) {
  process.stderr.write(`Error: ${message}\n\n${USAGE}`);
  process.exit(2);
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function parseArgs(argv) {
  const opts = {
    paginate: false,
    maxPages: DEFAULT_MAX_PAGES,
    maxItems: DEFAULT_MAX_ITEMS,
    timeoutMs: DEFAULT_TIMEOUT_MS,
  };
  const positionals = [];
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    const next = () => {
      const value = argv[++i];
      if (value === undefined) usageError(`Option ${arg} requires a value.`);
      return value;
    };
    switch (arg) {
      case '-h':
      case '--help':
        opts.help = true;
        break;
      case '--paginate':
        opts.paginate = true;
        break;
      case '--token':
        opts.token = next();
        break;
      case '--url':
        opts.baseUrl = next();
        break;
      case '--max-pages':
        opts.maxPages = parseInt(next(), 10);
        if (!Number.isInteger(opts.maxPages) || opts.maxPages < 1) {
          usageError('--max-pages must be a positive integer.');
        }
        break;
      case '--max-items':
        opts.maxItems = parseInt(next(), 10);
        if (!Number.isInteger(opts.maxItems) || opts.maxItems < 0) {
          usageError('--max-items must be a non-negative integer.');
        }
        break;
      case '--timeout':
        opts.timeoutMs = parseInt(next(), 10);
        if (!Number.isInteger(opts.timeoutMs) || opts.timeoutMs < 1) {
          usageError('--timeout must be a positive integer.');
        }
        break;
      default:
        if (arg.startsWith('--')) usageError(`Unknown option: ${arg}`);
        positionals.push(arg);
    }
  }
  if (positionals.length > 2) {
    usageError(`Unexpected extra arguments: ${positionals.slice(2).join(' ')}`);
  }
  opts.method = positionals[0];
  opts.jsonArgs = positionals[1];
  return opts;
}

function apiRequest(baseUrl, method, body, token, timeoutMs) {
  let url;
  try {
    url = new URL(baseUrl + method);
  } catch (err) {
    usageError(`Invalid API URL: ${baseUrl}${method}`);
  }
  const lib = url.protocol === 'https:' ? https : http;
  const payload = JSON.stringify(body);
  return new Promise((resolve, reject) => {
    const req = lib.request(
      url,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
          'Content-Length': Buffer.byteLength(payload),
        },
        timeout: timeoutMs,
      },
      (res) => {
        const chunks = [];
        res.on('data', (chunk) => chunks.push(chunk));
        res.on('end', () => {
          const text = Buffer.concat(chunks).toString('utf8');
          let data;
          try {
            data = JSON.parse(text);
          } catch {
            reject(
              new Error(
                `Non-JSON response (HTTP ${res.statusCode}) from ${method}: ${text.slice(0, 200)}`,
              ),
            );
            return;
          }
          resolve({ statusCode: res.statusCode, headers: res.headers, data });
        });
      },
    );
    req.on('timeout', () =>
      req.destroy(new Error(`Request to ${method} timed out after ${timeoutMs}ms`)),
    );
    req.on('error', reject);
    req.end(payload);
  });
}

async function callWithRetry(baseUrl, method, body, token, timeoutMs, requestFn = apiRequest) {
  let lastErr = null;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    let res;
    try {
      res = await requestFn(baseUrl, method, body, token, timeoutMs);
    } catch (err) {
      lastErr = err;
      if (attempt < MAX_ATTEMPTS) {
        process.stderr.write(
          `Retrying after network error (attempt ${attempt}/${MAX_ATTEMPTS}): ${err.message}\n`,
        );
        await sleep(attempt * 1000);
        continue;
      }
      throw err;
    }
    if (res.statusCode === 429 || (res.statusCode >= 500 && res.statusCode < 600)) {
      if (attempt < MAX_ATTEMPTS) {
        const retryAfter = Number.parseFloat(res.headers['retry-after']);
        const delayMs = Number.isFinite(retryAfter)
          ? Math.min(Math.max(retryAfter, 0), 30) * 1000
          : attempt * 1000;
        process.stderr.write(
          `Retrying after HTTP ${res.statusCode} (attempt ${attempt}/${MAX_ATTEMPTS}, waiting ${Math.round(delayMs)}ms)...\n`,
        );
        await sleep(delayMs);
        continue;
      }
      throw new Error(`HTTP ${res.statusCode} after ${MAX_ATTEMPTS} attempts (${method})`);
    }
    return res.data;
  }
  throw lastErr;
}

async function collectPages(
  { method, args, token, baseUrl, timeoutMs, maxPages, paginate },
  requestFn = apiRequest,
) {
  const pages = [];
  let cursor = '';
  for (let page = 1; page <= maxPages; page++) {
    const body = { ...args };
    if (cursor) body.cursor = cursor;
    const data = await callWithRetry(baseUrl, method, body, token, timeoutMs, requestFn);
    if (!data.ok) {
      throw new SlackApiError(data.error || 'unknown_error', HINTS[data.error] || '', data.detail);
    }
    pages.push(data);
    if (!paginate) break;
    const nextCursor = data.response_metadata && data.response_metadata.next_cursor;
    if (!nextCursor) break;
    cursor = nextCursor;
  }
  return pages;
}

function mergePages(pages) {
  const merged = {};
  const keys = new Set(pages.flatMap((page) => Object.keys(page)));
  for (const key of keys) {
    const values = pages
      .map((page) => page[key])
      .filter((value) => value !== undefined && value !== null);
    if (values.length === 0) continue;
    if (values.every((value) => Array.isArray(value))) {
      merged[key] = values.flat();
    } else {
      merged[key] = values[values.length - 1];
    }
  }
  return merged;
}

function buildResult(pages, { paginate, maxItems }) {
  const result = pages.length === 1 ? { ...pages[0] } : mergePages(pages);
  delete result.response_metadata;
  if (paginate && pages.length > 1) {
    result._pagination = { pages: pages.length };
  }
  if (maxItems > 0) {
    const truncated = [];
    for (const [key, value] of Object.entries(result)) {
      if (Array.isArray(value) && value.length > maxItems) {
        result[key] = value.slice(0, maxItems);
        truncated.push({ key, shown: maxItems, total: value.length });
      }
    }
    if (truncated.length > 0) {
      result._truncated = truncated;
    }
  }
  return result;
}

async function main(argv = process.argv.slice(2), requestFn = apiRequest) {
  const opts = parseArgs(argv);
  if (opts.help) {
    process.stdout.write(USAGE);
    return 0;
  }
  if (!opts.method) usageError('Missing method argument.');

  const token = opts.token || process.env.SLACK_TOKEN;
  if (!token) {
    usageError('No Slack token. Pass --token TOKEN or set the SLACK_TOKEN environment variable.');
  }

  let args = {};
  if (opts.jsonArgs !== undefined) {
    try {
      args = JSON.parse(opts.jsonArgs);
    } catch (err) {
      usageError(`Invalid JSON args: ${err.message}`);
    }
    if (args === null || typeof args !== 'object' || Array.isArray(args)) {
      usageError('JSON args must be an object, e.g. {"channel":"C123"}');
    }
  }

  const baseUrl =
    (opts.baseUrl || process.env.SLACK_API_URL || DEFAULT_BASE_URL).replace(/\/+$/, '') + '/';

  try {
    const pages = await collectPages(
      {
        method: opts.method,
        args,
        token,
        baseUrl,
        timeoutMs: opts.timeoutMs,
        maxPages: opts.maxPages,
        paginate: opts.paginate,
      },
      requestFn,
    );
    const result = buildResult(pages, { paginate: opts.paginate, maxItems: opts.maxItems });
    process.stdout.write(JSON.stringify(result, null, 2) + '\n');
    return 0;
  } catch (err) {
    if (err instanceof SlackApiError) {
      const out = {
        ok: false,
        error: err.error,
        ...(err.hint ? { hint: err.hint } : {}),
        ...(err.detail ? { detail: err.detail } : {}),
      };
      process.stderr.write(JSON.stringify(out, null, 2) + '\n');
    } else {
      process.stderr.write(`Error: ${err.message}\n`);
    }
    return 1;
  }
}

if (require.main === module) {
  main()
    .then((code) => process.exit(code))
    .catch((err) => {
      process.stderr.write(`Error: ${err.message}\n`);
      process.exit(1);
    });
}

module.exports = {
  USAGE,
  HINTS,
  SlackApiError,
  parseArgs,
  apiRequest,
  callWithRetry,
  collectPages,
  mergePages,
  buildResult,
  main,
};

#!/usr/bin/env node
'use strict';
/**
 * Test harness for .codex/skills/slack-api/scripts/slack_api.cjs
 *
 * Network sockets are blocked for spawned children in this sandbox, so the
 * HTTP transport is exercised with injected fake transports in-process,
 * while CLI wiring (arg parsing, usage errors, exit codes) is tested by
 * spawning the script. A real-network probe against api.slack.com is
 * included as informational only.
 */

const { spawnSync } = require('node:child_process');
const path = require('node:path');

const SCRIPT = path.resolve(
  __dirname,
  '..',
  '.codex',
  'skills',
  'slack-api',
  'scripts',
  'slack_api.cjs',
);
const mod = require(SCRIPT);
const {
  parseArgs,
  mergePages,
  collectPages,
  buildResult,
  callWithRetry,
  SlackApiError,
  main,
} = mod;

const tests = [];
function test(name, fn) {
  tests.push({ name, fn });
}
function assert(cond, message) {
  if (!cond) throw new Error(message);
}
async function expectReject(promise, pattern, label) {
  try {
    await promise;
  } catch (err) {
    assert(pattern.test(err.message), `${label}: unexpected message: ${err.message}`);
    return err;
  }
  throw new Error(`${label}: expected rejection`);
}

function runCli(args, env = {}) {
  return spawnSync(process.execPath, [SCRIPT, ...args], {
    encoding: 'utf8',
    env: { ...process.env, ...env },
    timeout: 60000,
  });
}

async function captureMain(argv, requestFn) {
  const origOut = process.stdout.write;
  const origErr = process.stderr.write;
  let out = '';
  let err = '';
  process.stdout.write = (s) => {
    out += s;
    return true;
  };
  process.stderr.write = (s) => {
    err += s;
    return true;
  };
  try {
    const code = await main(argv, requestFn);
    return { code, out, err };
  } finally {
    process.stdout.write = origOut;
    process.stderr.write = origErr;
  }
}

const ok = (data, statusCode = 200, headers = {}) => ({ statusCode, headers, data });

// ---- CLI wiring (spawned; no network needed) ----

test('CLI: --help exits 0 and prints usage', () => {
  const r = runCli(['--help']);
  assert(r.status === 0, `exit ${r.status}; stderr: ${r.stderr}`);
  assert(r.stdout.includes('Usage:'), 'usage text missing');
});

test('CLI: missing method is a usage error (exit 2)', () => {
  const r = runCli(['--token', 'x']);
  assert(r.status === 2, `exit ${r.status}`);
  assert(/Missing method argument/.test(r.stderr), `unexpected: ${r.stderr}`);
});

test('CLI: missing token is a usage error (exit 2)', () => {
  const r = runCli(['auth.test'], { SLACK_TOKEN: '' });
  assert(r.status === 2, `exit ${r.status}`);
  assert(/SLACK_TOKEN/.test(r.stderr), `unexpected: ${r.stderr}`);
});

test('CLI: invalid JSON args is a usage error (exit 2)', () => {
  const r = runCli(['chat.postMessage', 'not json', '--token', 'x']);
  assert(r.status === 2, `exit ${r.status}`);
  assert(/Invalid JSON args/.test(r.stderr), `unexpected: ${r.stderr}`);
});

test('CLI: unknown option is a usage error (exit 2)', () => {
  const r = runCli(['auth.test', '--nope', '--token', 'x']);
  assert(r.status === 2, `exit ${r.status}`);
  assert(/Unknown option/.test(r.stderr), `unexpected: ${r.stderr}`);
});

test('CLI: non-object JSON args is a usage error (exit 2)', () => {
  const r = runCli(['auth.test', '[1,2]', '--token', 'x']);
  assert(r.status === 2, `exit ${r.status}`);
  assert(/must be an object/.test(r.stderr), `unexpected: ${r.stderr}`);
});

// ---- pure logic ----

test('mergePages concatenates arrays and keeps last scalar', () => {
  const merged = mergePages([
    { ok: true, channels: [{ id: 'C1' }], has_more: true },
    { ok: true, channels: [{ id: 'C2' }], has_more: false },
  ]);
  assert(merged.channels.length === 2, `channels: ${merged.channels.length}`);
  assert(merged.has_more === false, 'scalar should be last-wins');
  assert(!('response_metadata' in merged), 'unexpected key');
});

test('parseArgs parses flags and positionals', () => {
  const opts = parseArgs([
    'conversations.list',
    '{"types":"public_channel"}',
    '--token',
    'xoxb-t',
    '--paginate',
    '--max-items',
    '10',
    '--max-pages',
    '3',
  ]);
  assert(opts.method === 'conversations.list', `method: ${opts.method}`);
  assert(opts.jsonArgs === '{"types":"public_channel"}', 'jsonArgs');
  assert(opts.token === 'xoxb-t' && opts.paginate === true, 'flags');
  assert(opts.maxItems === 10 && opts.maxPages === 3, 'numeric flags');
});

// ---- collectPages / retry / error mapping (injected transport) ----

test('collectPages fetches one page without --paginate', async () => {
  let calls = 0;
  const transport = async () => {
    calls += 1;
    return ok({ ok: true, channels: [], response_metadata: { next_cursor: 'p2' } });
  };
  const pages = await collectPages(
    { method: 'conversations.list', args: {}, token: 't', baseUrl: 'http://x/', timeoutMs: 5000, maxPages: 10, paginate: false },
    transport,
  );
  assert(pages.length === 1 && calls === 1, `pages=${pages.length} calls=${calls}`);
});

test('collectPages follows cursors and caps at maxPages', async () => {
  let calls = 0;
  const transport = async () => {
    calls += 1;
    return ok({ ok: true, channels: [], response_metadata: { next_cursor: 'next' } });
  };
  const pages = await collectPages(
    { method: 'm', args: {}, token: 't', baseUrl: 'http://x/', timeoutMs: 5000, maxPages: 3, paginate: true },
    transport,
  );
  assert(pages.length === 3 && calls === 3, `pages=${pages.length} calls=${calls}`);
});

test('collectPages throws SlackApiError with hint on ok:false', async () => {
  const transport = async () => ok({ ok: false, error: 'invalid_auth' });
  const err = await expectReject(
    collectPages({ method: 'm', args: {}, token: 't', baseUrl: 'http://x/', timeoutMs: 5000, maxPages: 10, paginate: false }, transport),
    /invalid_auth/,
    'invalid_auth',
  );
  assert(err instanceof SlackApiError, 'should be SlackApiError');
  assert(/token/i.test(err.hint), `hint: ${err.hint}`);
});

test('callWithRetry retries 429 and succeeds', async () => {
  let calls = 0;
  const transport = async () => {
    calls += 1;
    if (calls === 1) return ok({ ok: false, error: 'rate_limited' }, 429, { 'retry-after': '0' });
    return ok({ ok: true, recovered: true });
  };
  const data = await callWithRetry('http://x/', 'm', {}, 't', 5000, transport);
  assert(data.ok && data.recovered === true && calls === 2, `calls=${calls}`);
});

test('callWithRetry retries on network error then succeeds', async () => {
  let calls = 0;
  const transport = async () => {
    calls += 1;
    if (calls === 1) throw new Error('connect ECONNREFUSED');
    return ok({ ok: true });
  };
  const data = await callWithRetry('http://x/', 'm', {}, 't', 5000, transport);
  assert(data.ok === true && calls === 2, `calls=${calls}`);
});

