#!/usr/bin/env node
'use strict';
/**
 * Task-local replica of the skill-creator packager:
 *   1. Validates the skill (mirrors validate_skill.cjs rules).
 *   2. Packages it as a .skill zip (pure Node: deflate + CRC32 + central dir).
 *   3. Verifies the archive by re-parsing and inflating every entry.
 *
 * Usage: node scratch/package.js <skill-folder> <output-dir>
 */

const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');

// ---- validation (mirrors skill-creator validate_skill.cjs) ----

function validateSkill(skillPath) {
  if (!fs.existsSync(skillPath) || !fs.statSync(skillPath).isDirectory()) {
    return { valid: false, message: `Path is not a directory: ${skillPath}` };
  }
  const skillMdPath = path.join(skillPath, 'SKILL.md');
  if (!fs.existsSync(skillMdPath)) {
    return { valid: false, message: 'SKILL.md not found' };
  }
  const content = fs.readFileSync(skillMdPath, 'utf8');
  if (!content.startsWith('---')) {
    return { valid: false, message: 'No YAML frontmatter found' };
  }
  const parts = content.split('---');
  if (parts.length < 3) {
    return { valid: false, message: 'Invalid frontmatter format' };
  }
  const frontmatterText = parts[1];
  const nameMatch = frontmatterText.match(/^name:\s*(.+)$/m);
  const descMatch = frontmatterText.match(
    /^description:\s*(?:'([^']*)'|"([^"]*)"|(.+))$/m,
  );
  if (!nameMatch) return { valid: false, message: 'Missing "name" in frontmatter' };
  if (!descMatch) {
    return { valid: false, message: 'Description must be a single-line string: description: ...' };
  }
  const name = nameMatch[1].trim();
  const description = (
    descMatch[1] !== undefined ? descMatch[1] : descMatch[2] !== undefined ? descMatch[2] : descMatch[3] || ''
  ).trim();
  if (description.includes('\n')) {
    return { valid: false, message: 'Description must be a single line (no newlines)' };
  }
  if (!/^[a-z0-9-]+$/.test(name)) {
    return { valid: false, message: `Name "${name}" should be hyphen-case` };
  }
  if (description.length > 1024) {
    return { valid: false, message: 'Description is too long (max 1024)' };
  }
  for (const file of getAllFiles(skillPath)) {
    const fileContent = fs.readFileSync(file, 'utf8');
    if (fileContent.includes('TODO:')) {
      return {
        valid: true,
        message: 'Skill has unresolved TODOs',
        warning: `Found unresolved TODO in ${path.relative(skillPath, file)}`,
      };
    }
  }
  return { valid: true, message: 'Skill is valid!' };
}

function getAllFiles(dir, fileList = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const name = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (!['node_modules', '.git', '__pycache__'].includes(entry.name)) {
        getAllFiles(name, fileList);
      }
    } else {
      fileList.push(name);
    }
  }
  return fileList;
}

// ---- minimal zip writer ----

function crc32(buf) {
  let crc = 0xffffffff;
  for (let i = 0; i < buf.length; i++) {
    crc ^= buf[i];
    for (let k = 0; k < 8; k++) crc = (crc >>> 1) ^ (0xedb88320 & -(crc & 1));
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function dosDateTime() {
  const now = new Date();
  const time = (now.getHours() << 11) | (now.getMinutes() << 5) | (now.getSeconds() >> 1);
  const date = ((now.getFullYear() - 1980) << 9) | ((now.getMonth() + 1) << 5) | now.getDate();
  return { time, date };
}

function buildLocal(entry) {
  const nameBuf = Buffer.from(entry.name, 'utf8');
  const comp = zlib.deflateRawSync(entry.data);
  const crc = crc32(entry.data);
  const { time, date } = dosDateTime();
  const head = Buffer.alloc(30);
  head.writeUInt32LE(0x04034b50, 0);
  head.writeUInt16LE(20, 4); // version needed
  head.writeUInt16LE(0x0800, 6); // UTF-8 names
  head.writeUInt16LE(8, 8); // deflate
  head.writeUInt16LE(time, 10);
  head.writeUInt16LE(date, 12);
  head.writeUInt32LE(crc, 14);
  head.writeUInt32LE(comp.length, 18);
  head.writeUInt32LE(entry.data.length, 22);
  head.writeUInt16LE(nameBuf.length, 26);
  head.writeUInt16LE(0, 28);
  return { head, comp, crc, nameBuf };
}

function buildCentral(local, offset, mode) {
  const buf = Buffer.alloc(46);
  buf.writeUInt32LE(0x02014b50, 0);
  buf.writeUInt16LE(20, 4); // version made by
  buf.writeUInt16LE(20, 6); // version needed
  buf.writeUInt16LE(0x0800, 8);
  buf.writeUInt16LE(8, 10); // deflate
  buf.writeUInt16LE(local.time, 12);
  buf.writeUInt16LE(local.date, 14);
  buf.writeUInt32LE(local.crc, 16);
  buf.writeUInt32LE(local.comp.length, 20);
  buf.writeUInt32LE(local.data.length, 24);
  buf.writeUInt16LE(local.nameBuf.length, 28);
  buf.writeUInt16LE(0, 30); // extra
  buf.writeUInt16LE(0, 32); // comment
  buf.writeUInt16LE(0, 34); // disk start
  buf.writeUInt16LE(0, 36); // internal attrs
  buf.writeUInt32LE(mode << 16, 38); // unix mode in external attrs
  buf.writeUInt32LE(offset, 42);
  return Buffer.concat([buf, local.nameBuf]);
}

function makeZip(entries) {
  const locals = [];
  const centralParts = [];
  let offset = 0;
  for (const entry of entries) {
    const local = buildLocal(entry);
    locals.push(Buffer.concat([local.head, local.nameBuf, local.comp]));
    centralParts.push(buildCentral(local, offset, entry.mode));
    offset += local.head.length + local.nameBuf.length + local.comp.length;
  }
  const central = Buffer.concat(centralParts);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);
  eocd.writeUInt16LE(0, 4);
  eocd.writeUInt16LE(0, 6);
  eocd.writeUInt16LE(entries.length, 8);
  eocd.writeUInt16LE(entries.length, 10);
  eocd.writeUInt32LE(central.length, 12);
  eocd.writeUInt32LE(offset, 16);
  eocd.writeUInt16LE(0, 20);
  return Buffer.concat([...locals, central, eocd]);
}

function collectEntries(skillPath) {
  const entries = [];
  (function walk(dir, rel) {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      const relPath = rel ? `${rel}/${entry.name}` : entry.name;
      if (entry.isDirectory()) {
        entries.push({ name: `${relPath}/`, data: Buffer.alloc(0), mode: 0o755 });
        walk(full, relPath);
      } else {
        const isScript = entry.name.endsWith('.cjs') || entry.name.endsWith('.sh');
        entries.push({ name: relPath, data: fs.readFileSync(full), mode: isScript ? 0o755 : 0o644 });
      }
    }
  })(skillPath, '');
  return entries;
}

// ---- verification: re-parse the zip and inflate every entry ----

function verifyZip(buf, entries) {
  const eocd = buf.length - 22;
  const count = buf.readUInt16LE(eocd + 10);
  const cdOffset = buf.readUInt32LE(eocd + 16);
  if (count !== entries.length) return `entry count mismatch: ${count} vs ${entries.length}`;
  let offset = cdOffset;
  for (let i = 0; i < count; i++) {
    if (buf.readUInt32LE(offset) !== 0x02014b50) return `bad central header at ${offset}`;
    const method = buf.readUInt16LE(offset + 10);
    const compSize = buf.readUInt32LE(offset + 20);
    const uncompSize = buf.readUInt32LE(offset + 24);
    const nameLen = buf.readUInt16LE(offset + 28);
    const extraLen = buf.readUInt16LE(offset + 30);
    const commentLen = buf.readUInt16LE(offset + 32);
    const localOffset = buf.readUInt32LE(offset + 42);
    const name = buf.slice(offset + 46, offset + 46 + nameLen).toString('utf8');
    if (buf.readUInt32LE(localOffset) !== 0x04034b50) return `bad local header for ${name}`;
    if (!name.endsWith('/')) {
      const localNameLen = buf.readUInt16LE(localOffset + 26);
      const localExtraLen = buf.readUInt16LE(localOffset + 28);
      const dataStart = localOffset + 30 + localNameLen + localExtraLen;
      const comp = buf.slice(dataStart, dataStart + compSize);
      const raw = method === 8 ? zlib.inflateRawSync(comp) : comp;
      if (raw.length !== uncompSize) return `size mismatch for ${name}`;
      const expected = entries.find((e) => e.name === name);
      if (expected && !raw.equals(expected.data)) return `content mismatch for ${name}`;
    }
    offset += 46 + nameLen + extraLen + commentLen;
  }
  return null;
}

// ---- main ----

async function main() {
  const args = process.argv.slice(2);
  if (args.length < 2) {
    console.log('Usage: node scratch/package.js <skill-folder> <output-dir>');
    process.exit(1);
  }
  const skillPath = path.resolve(args[0]);
  const outputDir = path.resolve(args[1]);
  const skillName = path.basename(skillPath);

  console.log('🔍 Validating skill...');
  const result = validateSkill(skillPath);
  if (!result.valid) {
    console.error(`❌ Validation failed: ${result.message}`);
    process.exit(1);
  }
  if (result.warning) {
    console.error(`❌ ${result.warning}`);
    console.log('Please resolve all TODOs before packaging.');
    process.exit(1);
  }
  console.log('✅ Skill is valid!');

  const entries = collectEntries(skillPath);
  const zip = makeZip(entries);

  const verifyError = verifyZip(zip, entries);
  if (verifyError) {
    console.error(`❌ Archive verification failed: ${verifyError}`);
    process.exit(1);
  }

  fs.mkdirSync(outputDir, { recursive: true });
  const outputFilename = path.join(outputDir, `${skillName}.skill`);
  fs.writeFileSync(outputFilename, zip);
  console.log(`✅ Successfully packaged skill to: ${outputFilename} (${zip.length} bytes, ${entries.length} entries)`);
  for (const e of entries) {
    if (!e.name.endsWith('/')) console.log(`   ${e.name} (${e.data.length} bytes)`);
  }
}

main();

#!/usr/bin/env node
/**
 * Slack Web API helper — deterministic, LLM-friendly wrapper.
 *
 * Sends POST requests with JSON bodies to the Slack Web API, handles
 * authentication, cursor pagination, automatic retries on 429/5xx, and
 * truncates large arrays in the output.
 *
 * Usage:
 *   node slack_api.cjs <method> '<json-args>' [options]
 *
 * Options:
 *   --token TOKEN   Slack token (default: $SLACK_TOKEN)
 *   --url URL       API base URL (default: $SLACK_API_URL or https://slack.com/api/)
 *   --paginate      Follow response_metadata.next_cursor until exhausted (max --max-pages pages)
 *   --max-pages N   Page cap when paginating (default: 10)
 *   --max-items N   Truncate arrays longer than N in output (default: 50; 0 disables)
 *   --timeout MS    Per-request timeout in milliseconds (default: 30000)
 *   -h, --help      Show this help
 *
 * Exit codes: 0 = success, 1 = API/network error, 2 = usage error.
 *
 * Examples:
 *   node slack_api.cjs auth.test
 *   node slack_api.cjs chat.postMessage '{"channel":"C123456","text":"Deploy complete"}'
 *   node slack_api.cjs conversations.list '{"types":"public_channel"}' --paginate
 *   node slack_api.cjs chat.postMessage '{"channel":"C123456","thread_ts":"1700000000.123456","text":"Thread reply"}'
 */
'use strict';

const http = require('node:http');
const https = require('node:https');

const DEFAULT_BASE_URL = 'https://slack.com/api/';
const DEFAULT_MAX_PAGES = 10;
const DEFAULT_MAX_ITEMS = 50;
const DEFAULT_TIMEOUT_MS = 30000;
const MAX_ATTEMPTS = 3;

const USAGE = `Slack Web API helper

Usage:
  node slack_api.cjs <method> '<json-args>' [options]

Options:
  --token TOKEN   Slack token (default: \$SLACK_TOKEN)
  --url URL       API base URL (default: \$SLACK_API_URL or https://slack.com/api/)
  --paginate      Follow response_metadata.next_cursor until exhausted (max --max-pages pages)
  --max-pages N   Page cap when paginating (default: 10)
  --max-items N   Truncate arrays longer than N in output (default: 50; 0 disables)
  --timeout MS    Per-request timeout in milliseconds (default: 30000)
  -h, --help      Show this help

Exit codes: 0 = success, 1 = API/network error, 2 = usage error.

Examples:
  node slack_api.cjs auth.test
  node slack_api.cjs chat.postMessage '{"channel":"C123456","text":"Deploy complete"}'
  node slack_api.cjs conversations.list '{"types":"public_channel"}' --paginate
  node slack_api.cjs chat.postMessage '{"channel":"C123456","thread_ts":"1700000000.123456","text":"Thread reply"}'
`;

const HINTS = {
  invalid_auth:
    'Check the token (--token or $SLACK_TOKEN). Use a bot token (xoxb-...) or user token (xoxp-...).',
  invalid_auth_token:
    'The token is not valid for this workspace. Generate a fresh token from the Slack app.',
  account_inactive:
    'The token belongs to a deactivated user or app. Check the Slack app status.',
  token_revoked:
    'The token was revoked. Create a new token in the Slack app.',
  missing_scope:
    'The token lacks the required OAuth scope for this method. Add the scope to the Slack app and reinstall it.',
  not_in_channel:
    'The bot/user is not a member of that channel. Invite it first with conversations.invite.',
  channel_not_found:
    'Use a channel ID (C...), not a name. Find it with conversations.list.',
  is_archived:
    'The channel is archived. Unarchive it first with conversations.unarchive.',
  rate_limited:
    'Rate limit hit. The script retries automatically; if this persists, wait and retry.',
  invalid_arguments:
    'One of the parameters is invalid. Check the method documentation in references/api.md.',
  internal_error:
    'Slack-side error. Retry the request.',
};

function usageError(message) {
  process.stderr.write(`Error: ${message}\n\n${USAGE}`);
  process.exit(2);
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function parseArgs(argv) {
  const opts = {
    paginate: false,
    maxPages: DEFAULT_MAX_PAGES,
    maxItems: DEFAULT_MAX_ITEMS,
    timeoutMs: DEFAULT_TIMEOUT_MS,
  };
  const positionals = [];
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    const next = () => {
      const value = argv[++i];
      if (value === undefined) usageError(`Option ${arg} requires a value.`);
      return value;
    };
    switch (arg) {
      case '-h':
      case '--help':
        opts.help = true;
        break;
      case '--paginate':
        opts.paginate = true;
        break;
      case '--token':
        opts.token = next();
        break;
      case '--url':
        opts.baseUrl = next();
        break;
      case '--max-pages':
        opts.maxPages = parseInt(next(), 10);
        if (!Number.isInteger(opts.maxPages) || opts.maxPages < 1) {
          usageError('--max-pages must be a positive integer.');
        }
        break;
      case '--max-items':
        opts.maxItems = parseInt(next(), 10);
        if (!Number.isInteger(opts.maxItems) || opts.maxItems < 0) {
          usageError('--max-items must be a non-negative integer.');
        }
        break;
      case '--timeout':
        opts.timeoutMs = parseInt(next(), 10);
        if (!Number.isInteger(opts.timeoutMs) || opts.timeoutMs < 1) {
          usageError('--timeout must be a positive integer.');
        }
        break;
      default:
        if (arg.startsWith('--')) usageError(`Unknown option: ${arg}`);
        positionals.push(arg);
    }
  }
  if (positionals.length > 2) {
    usageError(`Unexpected extra arguments: ${positionals.slice(2).join(' ')}`);
  }
  opts.method = positionals[0];
  opts.jsonArgs = positionals[1];
  return opts;
}

function apiRequest(baseUrl, method, body, token, timeoutMs) {
  let url;
  try {
    url = new URL(baseUrl + method);
  } catch (err) {
    usageError(`Invalid API URL: ${baseUrl}${method}`);
  }
  const lib = url.protocol === 'https:' ? https : http;
  const payload = JSON.stringify(body);
  return new Promise((resolve, reject) => {
    const req = lib.request(
      url,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
          'Content-Length': Buffer.byteLength(payload),
        },
        timeout: timeoutMs,
      },
      (res) => {
        const chunks = [];
        res.on('data', (chunk) => chunks.push(chunk));
        res.on('end', () => {
          const text = Buffer.concat(chunks).toString('utf8');
          let data;
          try {
            data = JSON.parse(text);
          } catch {
            reject(
              new Error(
                `Non-JSON response (HTTP ${res.statusCode}) from ${method}: ${text.slice(0, 200)}`,
              ),
            );
            return;
          }
          resolve({ statusCode: res.statusCode, headers: res.headers, data });
        });
      },
    );
    req.on('timeout', () =>
      req.destroy(new Error(`Request to ${method} timed out after ${timeoutMs}ms`)),
    );
    req.on('error', reject);
    req.end(payload);
  });
}

async function callWithRetry(baseUrl, method, body, token, timeoutMs) {
  let lastErr = null;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    let res;
    try {
      res = await apiRequest(baseUrl, method, body, token, timeoutMs);
    } catch (err) {
      lastErr = err;
      if (attempt < MAX_ATTEMPTS) {
        process.stderr.write(
          `Retrying after network error (attempt ${attempt}/${MAX_ATTEMPTS}): ${err.message}\n`,
        );
        await sleep(attempt * 1000);
        continue;
      }
      throw err;
    }
    if (res.statusCode === 429 || (res.statusCode >= 500 && res.statusCode < 600)) {
      if (attempt < MAX_ATTEMPTS) {
        const retryAfter = Number.parseFloat(res.headers['retry-after']);
        const delayMs = Number.isFinite(retryAfter)
          ? Math.min(Math.max(retryAfter, 0), 30) * 1000
          : attempt * 1000;
        process.stderr.write(
          `Retrying after HTTP ${res.statusCode} (attempt ${attempt}/${MAX_ATTEMPTS}, waiting ${Math.round(delayMs)}ms)...\n`,
        );
        await sleep(delayMs);
        continue;
      }
      throw new Error(`HTTP ${res.statusCode} after ${MAX_ATTEMPTS} attempts (${method})`);
    }
    return res.data;
  }
  throw lastErr;
}

function mergePages(pages) {
  const merged = {};
  const keys = new Set(pages.flatMap((page) => Object.keys(page)));
  for (const key of keys) {
    const values = pages
      .map((page) => page[key])
      .filter((value) => value !== undefined && value !== null);
    if (values.length === 0) continue;
    if (values.every((value) => Array.isArray(value))) {
      merged[key] = values.flat();
    } else {
      merged[key] = values[values.length - 1];
    }
  }
  return merged;
}

async function main() {
  const opts = parseArgs(process.argv.slice(2));
  if (opts.help) {
    process.stdout.write(USAGE);
    process.exit(0);
  }
  if (!opts.method) usageError('Missing method argument.');

  const token = opts.token || process.env.SLACK_TOKEN;
  if (!token) {
    usageError('No Slack token. Pass --token TOKEN or set the SLACK_TOKEN environment variable.');
  }

  let args = {};
  if (opts.jsonArgs !== undefined) {
    try {
      args = JSON.parse(opts.jsonArgs);
    } catch (err) {
      usageError(`Invalid JSON args: ${err.message}`);
    }
    if (args === null || typeof args !== 'object' || Array.isArray(args)) {
      usageError('JSON args must be an object, e.g. {"channel":"C123"}');
    }
  }

  const baseUrl = (opts.baseUrl || process.env.SLACK_API_URL || DEFAULT_BASE_URL).replace(/\/+$/, '') + '/';

  const pages = [];
  let cursor = '';
  for (let page = 1; page <= opts.maxPages; page++) {
    const body = { ...args };
    if (cursor) body.cursor = cursor;
    const data = await callWithRetry(baseUrl, opts.method, body, token, opts.timeoutMs);
    if (!data.ok) {
      const hint = HINTS[data.error] || '';
      const out = {
        ok: false,
        error: data.error || 'unknown_error',
        ...(hint ? { hint } : {}),
        ...(data.detail ? { detail: data.detail } : {}),
      };
      process.stderr.write(JSON.stringify(out, null, 2) + '\n');
      process.exit(1);
    }
    pages.push(data);
    if (!opts.paginate) break;
    const nextCursor = data.response_metadata && data.response_metadata.next_cursor;
    if (!nextCursor) break;
    cursor = nextCursor;
  }

  const result = pages.length === 1 ? { ...pages[0] } : mergePages(pages);
  delete result.response_metadata;
  if (opts.paginate && pages.length > 1) {
    result._pagination = { pages: pages.length };
  }

  if (opts.maxItems > 0) {
    const truncated = [];
    for (const [key, value] of Object.entries(result)) {
      if (Array.isArray(value) && value.length > opts.maxItems) {
        result[key] = value.slice(0, opts.maxItems);
        truncated.push({ key, shown: opts.maxItems, total: value.length });
      }
    }
    if (truncated.length > 0) {
      result._truncated = truncated;
    }
  }

  process.stdout.write(JSON.stringify(result, null, 2) + '\n');
  process.exit(0);
}

main().catch((err) => {
  process.stderr.write(`Error: ${err.message}\n`);
  process.exit(1);
});

'use strict';
/**
 * Test harness for .codex/skills/slack-api/scripts/slack_api.cjs
 * Spins up a mock Slack API server and exercises the helper end-to-end.
 */

const http = require('node:http');
const { spawnSync } = require('node:child_process');
const path = require('node:path');

const SCRIPT = path.resolve(
  __dirname,
  '..',
  '.codex',
  'skills',
  'slack-api',
  'scripts',
  'slack_api.cjs',
);

let rateLimitHits = 0;

const server = http.createServer((req, res) => {
  let body = '';
  req.on('data', (chunk) => (body += chunk));
  req.on('end', () => {
    let payload = {};
    try {
      payload = JSON.parse(body || '{}');
    } catch {
      /* ignore */
    }
    const auth = req.headers['authorization'] || '';
    const send = (code, obj, extraHeaders = {}) => {
      res.writeHead(code, { 'Content-Type': 'application/json', ...extraHeaders });
      res.end(JSON.stringify(obj));
    };
    const method = req.url.slice(1);
    switch (method) {
      case 'auth.test':
        if (auth !== 'Bearer xoxb-test') {
          return send(200, { ok: false, error: 'invalid_auth' });
        }
        send(200, {
          ok: true,
          url: 'https://mock.slack.com/',
          user: 'U123',
          user_id: 'U123',
          team_id: 'T123',
          team: 'Mock Workspace',
        });
        break;
      case 'chat.postMessage':
        if (payload.channel !== 'C123') {
          return send(200, { ok: false, error: 'channel_not_found' });
        }
        send(200, {
          ok: true,
          channel: 'C123',
          ts: '1700000000.123456',
          message: { type: 'message', user: 'U123', text: payload.text, ts: '1700000000.123456' },
        });
        break;
      case 'conversations.list': {
        if (payload.cursor === 'page2') {
          send(200, {
            ok: true,
            channels: [{ id: 'C4' }, { id: 'C5' }],
            response_metadata: { next_cursor: '' },
          });
        } else {
          send(200, {
            ok: true,
            channels: [{ id: 'C1' }, { id: 'C2' }, { id: 'C3' }],
            response_metadata: { next_cursor: 'page2' },
          });
        }
        break;
      }
      case 'conversations.history': {
        const messages = Array.from({ length: 120 }, (_, i) => ({
          type: 'message',
          ts: `${1700000000 + i}.000000`,
          text: `msg ${i}`,
        }));
        send(200, {
          ok: true,
          messages,
          has_more: false,
          response_metadata: { next_cursor: '' },
        });
        break;
      }
      case 'invalid_auth_test':
        send(200, { ok: false, error: 'invalid_auth' });
        break;
      case 'rate.limited': {
        rateLimitHits += 1;
        if (rateLimitHits === 1) {
          return send(429, { ok: false, error: 'rate_limited' }, { 'Retry-After': '0' });
        }
        send(200, { ok: true, recovered: true, hits: rateLimitHits });
        break;
      }
      case 'server.error':
        send(500, { ok: false, error: 'internal_error' });
        break;
      default:
        send(200, { ok: false, error: 'method_not_found' });
    }
  });
});

function run(args, env = {}) {
  return spawnSync(process.execPath, [SCRIPT, ...args], {
    encoding: 'utf8',
    env: { ...process.env, SLACK_API_URL: BASE, ...env },
    timeout: 60000,
  });
}

const tests = [];
function test(name, fn) {
  tests.push({ name, fn });
}

function assert(cond, message) {
  if (!cond) throw new Error(message);
}

test('auth.test succeeds with Bearer token', () => {
  const r = run(['auth.test', '--token', 'xoxb-test']);
  assert(r.status === 0, `exit ${r.status}; stderr: ${r.stderr}`);
  const out = JSON.parse(r.stdout);
  assert(out.ok === true && out.user_id === 'U123', `unexpected output: ${r.stdout}`);
  assert(!('response_metadata' in out), 'response_metadata should be dropped');
});

test('chat.postMessage posts and returns ts', () => {
  const r = run(['chat.postMessage', '{"channel":"C123","text":"hello"}', '--token', 'xoxb-test']);
  assert(r.status === 0, `exit ${r.status}; stderr: ${r.stderr}`);
  const out = JSON.parse(r.stdout);
  assert(out.ok === true && out.ts === '1700000000.123456', `unexpected output: ${r.stdout}`);
});

test('API error exits 1, prints hint to stderr, stdout empty', () => {
  const r = run(['chat.postMessage', '{"channel":"NOPE","text":"hi"}', '--token', 'xoxb-test']);
  assert(r.status === 1, `exit ${r.status}`);
  assert(r.stdout === '', 'stdout should be empty on API error');
  const err = JSON.parse(r.stderr);
  assert(err.error === 'channel_not_found', `unexpected error: ${r.stderr}`);
  assert(/channel ID/.test(err.hint), `missing hint: ${r.stderr}`);
});

test('--paginate merges pages', () => {
  const r = run(['conversations.list', '{}', '--token', 'xoxb-test', '--paginate']);
  assert(r.status === 0, `exit ${r.status}; stderr: ${r.stderr}`);
  const out = JSON.parse(r.stdout);
  assert(out.channels.length === 5, `expected 5 merged channels, got ${out.channels.length}`);
  assert(out._pagination && out._pagination.pages === 2, `missing _pagination: ${r.stdout}`);
});

test('large arrays are truncated with _truncated note', () => {
  const r = run(['conversations.history', '{}', '--token', 'xoxb-test']);
  assert(r.status === 0, `exit ${r.status}; stderr: ${r.stderr}`);
  const out = JSON.parse(r.stdout);
  assert(out.messages.length === 50, `expected 50 truncated messages, got ${out.messages.length}`);
  assert(
    out._truncated && out._truncated[0].total === 120,
    `missing _truncated note: ${r.stdout.slice(0, 300)}`,
  );
});

test('invalid_auth error carries token hint', () => {
  const r = run(['invalid_auth_test', '--token', 'xoxb-test']);
  assert(r.status === 1, `exit ${r.status}`);
  const err = JSON.parse(r.stderr);
  assert(err.error === 'invalid_auth' && /token/i.test(err.hint), `unexpected: ${r.stderr}`);
});

test('429 is retried and succeeds', () => {
  const r = run(['rate.limited', '--token', 'xoxb-test']);
  assert(r.status === 0, `exit ${r.status}; stderr: ${r.stderr}`);
  const out = JSON.parse(r.stdout);
  assert(out.ok === true && out.hits === 2, `expected retry success: ${r.stdout}`);
  assert(/Retrying after HTTP 429/.test(r.stderr), `expected retry notice: ${r.stderr}`);
});

test('5xx exhausts retries and exits 1', () => {
  const r = run(['server.error', '--token', 'xoxb-test']);
  assert(r.status === 1, `exit ${r.status}`);
  assert(/HTTP 500 after 3 attempts/.test(r.stderr), `unexpected: ${r.stderr}`);
});

test('missing token is a usage error (exit 2)', () => {
  const r = run(['auth.test'], { SLACK_TOKEN: '' });
  assert(r.status === 2, `exit ${r.status}`);
  assert(/SLACK_TOKEN/.test(r.stderr), `unexpected: ${r.stderr}`);
});

test('invalid JSON args is a usage error (exit 2)', () => {
  const r = run(['chat.postMessage', 'not json', '--token', 'xoxb-test']);
  assert(r.status === 2, `exit ${r.status}`);
  assert(/Invalid JSON args/.test(r.stderr), `unexpected: ${r.stderr}`);
});

test('unknown option is a usage error (exit 2)', () => {
  const r = run(['auth.test', '--nope', '--token', 'xoxb-test']);
  assert(r.status === 2, `exit ${r.status}`);
  assert(/Unknown option/.test(r.stderr), `unexpected: ${r.stderr}`);
});

async function main() {
  console.log(`node ${process.version}`);
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  const port = server.address().port;
  global.BASE = `http://127.0.0.1:${port}/`;

  let failed = 0;
  for (const t of tests) {
    try {
      t.fn();
      console.log(`PASS: ${t.name}`);
    } catch (err) {
      failed += 1;
